// ui-deviation.js — generated by the modularisation of index.html; see README for what lives where.
import { t } from './i18n.js';
import { esc, foldHtml, hapticTap, lastUpdateFooter, locationsCfg, phIcon, showToast, twoStepConfirm } from './ui-common.js';
import { ATC_NAME, CITY_AFC, CITY_ATC, FREE_TEXT_MAX, carStdId, destinationFor, freeText, routeLabel } from './locations.js';
import { activeDeviation, computeRideDeparture, driverNameHtml, effectiveCars, fam, girlName, isAvailable, isFlex, seats, sortFamEntriesByGirl, sortGirlIds, tripReserveIds } from './rides.js';
import { S } from './state.js';
import { db, recordLastUpdate, saveDeviationCars } from './data.js';
import { buildConclusieMessage, buildWhatsAppMessage, reserveAskText } from './message-texts.js';
import { DAYS, WHATSAPP_SVG, todayKey } from './constants.js';
import { dateForWeekday, dayUp, deviationExpiryMs, deviationKey, refreshWeekKey, weekRangeLabel } from './dates.js';
import { dayCoordinatorFor, myFamilyId, myLinkedFamilyId } from './coordinator.js';
import { contactButtonHtml } from './ui-contact.js';
import { markPeriodShown, periodCardsHtml, periodFormActive, periodFormHtml, wirePeriod } from './ui-period.js';
import { ritbeursAvailable, ritbeursSegmentHtml, ritbeursViewHtml, wireRitbeurs, wireRitbeursSegment } from './ui-ritbeurs.js';
import { carsWithFreeSeat, flexDriveOwn, flexIsSignedUp, flexJoinCar, flexSignOff } from './flex.js';

export function sendWhatsAppUpdate(buildFn){
  const msg = (typeof buildFn==='function'? buildFn : buildWhatsAppMessage)();
  window.open('https://wa.me/?text='+encodeURIComponent(msg), '_blank', 'noopener,noreferrer');
}

export function whatsAppButtonHtml(btnId){
  btnId = btnId || 'waUpdateBtn';
  return `<button type="button" class="btn secondary" id="${btnId}" style="display:inline-flex;align-items:center">${WHATSAPP_SVG}${t('deviation.deel_update_via_whatsapp')}</button>`;
}

export function wireWhatsAppButton(btnId, buildFn){
  const btn=document.getElementById(btnId || 'waUpdateBtn');
  if(btn) btn.onclick=()=>sendWhatsAppUpdate(buildFn);
}

// One line describing a Weekschema change (see diffWeekschema), e.g. "Dinsdag Heen: tijd 08:30 → 09:00".
export function describeWeekschemaChange(c){
  const day = (DAYS.find(([k])=>k===c.day)||[c.day,c.day])[1];
  const dir = c.direction==='heen'? t('dir.heenShort') : t('dir.terugShort');
  if(c.kind==='time') return t('weekschema.tijd',{p1:day,p2:dir,p3:c.from||t('weekschema.geen_tijd'),p4:c.to||t('weekschema.geen_tijd')});
  if(c.kind==='drive') return t(c.to? 'weekschema.rijdt_aan' : 'weekschema.rijdt_uit',{p1:day,p2:dir});
  return t(c.to? 'weekschema.backup_aan' : 'weekschema.backup_uit',{p1:day,p2:dir});
}

// Set by Mijn gezin's "Eenmalig wijzigen": what the parent wanted to change, shown until closed.
export function deviationIntentHtml(){
  const list = S.deviationIntent;
  if(!list || !list.length) return '';
  return `<div class="alertCard alertCard--stack devIntent" id="devIntent" role="status">
    <div class="alertCard__text"><b><span class="alertCard__icon">${phIcon('lightning')}</span> ${t('deviation.intent_titel')}</b></div>
    <ul class="devIntentList">${list.map(c=>`<li>${esc(describeWeekschemaChange(c))}</li>`).join('')}</ul>
    <p class="noteLine">${t('deviation.intent_hint')}</p>
    <button type="button" class="btn small secondary" id="devIntentClose">${t('deviation.intent_sluiten')}</button>
  </div>`;
}

export function renderDeviationTab(){
  const box=document.getElementById('tab-deviation');
  if(!box) return;
  if(!S.me){ box.innerHTML=`<div class="card"><h2>${t('deviation.wijzigen')}</h2><p class="muted">${t('deviation.kon_je_account_niet_herkennen')}</p></div>`; markPeriodShown(); return; }
  // Periode met andere tijden: while the form is open it is all Wijzigen shows.
  if(periodFormActive()){ box.innerHTML = periodFormHtml(); wirePeriod(); markPeriodShown(); return; }
  // Ritbeurs (only while the feature switch is on): a segment "Wijzigen | Ritbeurs" at the top; the Ritbeurs view replaces the rest.
  const rbOn = ritbeursAvailable();
  if(!rbOn && S.rbView==='ritbeurs') S.rbView = 'wijzigen';
  const seg = rbOn? ritbeursSegmentHtml() : '';
  if(rbOn && S.rbView==='ritbeurs'){ box.innerHTML = seg + ritbeursViewHtml(); wireRitbeurs(); markPeriodShown(); return; }
  // Same as Rooster: a day is always open (today, or Monday on a weekend) and a tap on a pill loads that day.
  if(!S.deviationDay || !DAYS.some(([k])=>k===S.deviationDay)) S.deviationDay = todayKey || 'Ma';
  const day = S.deviationDay;
  const dayLabel = DAYS.find(([k])=>k===day)[1];
  const changedDays = DAYS.filter(([k])=>activeDeviation(k,'heen')||activeDeviation(k,'terug')).map(([k])=>k);
  const pillsHtml = DAYS.map(([k,label])=>{
    const changed = changedDays.includes(k);
    const isActive = k===day;
    const isToday = k===todayKey;
    return `<button type="button" class="dayPill devDayPill${isActive?' on':''}${isToday?' dayPill--today':''}${changed?' changed':''}" data-devday="${k}" aria-pressed="${isActive}" aria-label="${label} ${dateForWeekday(k).getDate()}${changed?t('deviation.gewijzigd'):''}">
      <span class="dayPill__ab">${isToday? esc(t('myweek.vandaag').toLowerCase()) : dayUp(k).toLowerCase()}</span>
      <span class="dayPill__n">${dateForWeekday(k).getDate()}</span>
      ${changed? '<span class="dayPill__dot" aria-hidden="true"></span>' : ''}
    </button>`;
  }).join('');
  box.innerHTML = `${seg}${periodCardsHtml()}${deviationIntentHtml()}
    <div class="dayPills" role="group" aria-label="${t('deviation.kies_een_dag')}">${pillsHtml}</div>
    <div class="infoLine"><span class="infoLine__text">${t('deviation.eenmalige_ritaanpassing_voor_deze_week')} ${weekRangeLabel()}. ${t('deviation.wijzigingen_hier_gelden_alleen_voor')} ${dayLabel.toLowerCase()} ${t('deviation.deze_week_en_verdwijnen_dit')}</span></div>
    ${changedDays.length? `<p class="noteLine"><span class="dayPill__dot dayPill__dot--inline" aria-hidden="true"></span> ${t('deviation.deze_week_gewijzigd')}</p>` : ''}
    <div class="daysection"><h3 class="srOnly">${dayLabel}</h3>
      ${renderDevDirection(day,'heen')}
      ${renderDevDirection(day,'terug')}
      ${conclusieCardHtml(day)}
    </div>
    ${lastUpdateFooter(S.lastUpdateDeviation)}`;
  document.querySelectorAll('[data-devday]').forEach(b=>b.onclick=()=>{ S.deviationDay=b.dataset.devday; S.devKid=null; S.devUndo=null; hapticTap(); renderDeviationTab(); });
  const ic=document.getElementById('devIntentClose'); if(ic) ic.onclick=()=>{ S.deviationIntent=null; hapticTap(); renderDeviationTab(); };
  wireWhatsAppButton('conclusieBtn', ()=>buildConclusieMessage(day));
  wireRitbeursSegment();
  attachDeviationHandlers();
  wirePeriod();
  markPeriodShown();
}

// US-03: the auto-drafted "conclusie-appje" for the open day. Highlighted for that day's coordinator (US-02);
// every other parent can use it too. The button only opens WhatsApp with the text filled in: nothing is sent.
export function conclusieCardHtml(day){
  const dayLabel = DAYS.find(([k])=>k===day)[1];
  const dc = dayCoordinatorFor(S, day);
  const me = myLinkedFamilyId();
  const forYou = !!(dc && me && dc.familyId===me);
  return `<div class="card conclusieCard${forYou?' forYou':''}" id="conclusieCard">
    <h2>${t('conclusie.title', { dayLabel })}</h2>
    <p class="noteLine" style="margin:0">${forYou? t('conclusie.forYou', { day: dayLabel.toLowerCase() }) : t('conclusie.intro')}</p>
    <div class="conclusiePreview" aria-label="${t('conclusie.previewLabel')}">${esc(buildConclusieMessage(day))}</div>
    <button type="button" class="btn" id="conclusieBtn" style="width:100%">${phIcon('whatsapp-logo-fill')}${t('conclusie.button')}</button>
  </div>`;
}

// US-05: Flex families sign up per day and direction, as passenger or as driver.
// A parent sees their own family (when it is Flex); the coordinator sees every Flex family.
export function flexSignupHtml(day,direction,cars){
  const mine = myLinkedFamilyId();
  const flexFams = sortFamEntriesByGirl(Object.entries(S.families).filter(([id,f])=>isFlex(f) && (S.canEdit || id===mine)));
  if(!flexFams.length) return '';
  const freeIdx = carsWithFreeSeat(cars, id=>seats(fam(id)));
  const timeLabel = direction==='heen'? t('flex.timeHeen') : t('flex.timeTerug');
  const rows = flexFams.map(([id,f])=>{
    const key = `${day}|${direction}|${id}`;
    const head = `<strong>${esc(f.girlName||f.parentName||id)}</strong> <span class="badge flexBadge">${t('flex.badge')}</span>`;
    if(flexIsSignedUp(cars,id)){
      return `<div class="rowflex flexRow" style="padding:6px 0;border-bottom:1px solid var(--line)"><span style="flex:1">${head} · ${t('flex.signedUp')}</span>
        <button type="button" class="btn small secondary" data-flexoff="${key}">${t('flex.signOff')}</button></div>`;
    }
    const carOptions = `<option value="">${t('flex.chooseCar')}</option>` + freeIdx.map(i=>`<option value="${i}">${t('deviation.auto')} ${driverNameHtml(cars[i].driverFamilyId)}</option>`).join('');
    const canDrive = seats(f)>=1;
    return `<div class="flexRow" style="padding:6px 0;border-bottom:1px solid var(--line)">
      <div>${head}</div>
      <label style="margin-top:6px" for="flexTime_${key}">${timeLabel}</label>
      <input type="time" id="flexTime_${key}" class="flexTimeInp">
      <div class="rowflex" style="gap:6px;margin-top:6px;flex-wrap:wrap">
        ${freeIdx.length? `<select id="flexCar_${key}" class="flexCarSel" style="width:auto">${carOptions}</select>
        <button type="button" class="btn small" data-flexpass="${key}">${t('flex.rideAlong')}</button>` : `<span class="muted">${t('flex.noFreeSeat')}</span>`}
        ${canDrive? `<button type="button" class="btn small secondary" data-flexdrive="${key}">${phIcon('car')} ${t('flex.drive')}</button>` : `<span class="muted">${t('flex.noCarToDrive')}</span>`}
      </div>
    </div>`;
  }).join('');
  return foldHtml(`flex|${day}|${direction}`, t('flex.title'), `<p class="muted" style="margin:0 0 4px">${t('flex.intro')}</p>
    ${rows}`, 'group flexSignup');
}

// Back-up drivers of one shift: the reserves in the order of the Selectievolgorde, without anyone who already drives a car of this
// shift (tripReserveIds leaves them out). Each name asks that reserve by WhatsApp; your own name is plain text.
export function backupHtml(day,direction,cars){
  const ids = tripReserveIds(day,direction,cars);
  if(!ids.length) return '';
  const me = myLinkedFamilyId();
  const withRiders = cars.filter(c=>(c.girlIds||[]).length);
  const askCar = withRiders.find(c=>me && c.driverFamilyId===me) || withRiders.find(c=>me && c.girlIds.includes(me)) || withRiders[0];
  const ask = reserveAskText(day,direction,askCar && askCar.departureTime);
  const names = ids.map(id=> id===me? esc(fam(id).parentName||'?') : contactButtonHtml(id, esc(fam(id).parentName||'?'), ask));
  return `<div class="noteLine tripReserve backup">${t('deviation.backup')} ${names.join(', ')}</div>`;
}

// The title of one direction: "Heen" / "Terug" with where it goes to. It follows the arrival place of the rides (AFC '34 = Alkmaar, ATC = Wijdewormer).
function devDirHeader(direction,cars){
  const cfg = locationsCfg();
  const cities = [...new Set(cars.map(c=>destinationFor(c,cfg).city))];
  if(!cities.length) cities.push(CITY_AFC);
  return `<div class="sectionHead"><div class="sectionHead__title">${direction==='heen'? t('dir.heenShort') : t('dir.terugShort')}</div><div class="sectionHead__sub">${esc(t(direction==='heen'? 'dir.heenTo' : 'dir.terugFrom', { city: cities.join(' / ') }))}</div></div>`;
}

const rawGirlName = id => fam(id).girlName||fam(id).parentName||id;

// One ride as a compact card. Closed: one line (time, driver, route) and the passengers. "Wijzig" unfolds the form.
function devRideHtml(day,direction,idx,cars,ctx){
  const c = cars[idx], key = `${day}|${direction}|${idx}`;
  const { allFamilies, myIdDev, locCfg } = ctx;
  const open = !!S.devOpen[key];
  const dest = destinationFor(c, locCfg);
  const route = routeLabel(c, direction, locCfg, day);
  const mine = id => id===myIdDev;
  const girls = sortGirlIds(c.girlIds);
  const undo = S.devUndo && S.devUndo.key===key? S.devUndo : null;
  const head = `<button type="button" class="devRideHead" data-devtoggle="${key}" aria-expanded="${open}">
      <span class="devRideTime">${c.departureTime? esc(c.departureTime) : '--:--'}</span>
      <span class="devRideMain"><span class="devRideDriver">${driverNameHtml(c.driverFamilyId)}</span><span class="devRideRoute">${esc(route)}</span></span>
      <span class="devRideToggle">${open? t('deviation.klaar') : t('deviation.wijzig')}</span>
    </button>`;
  let body;
  if(!open){
    body = `<div class="chips">${girls.map(id=>`<span class="chip${mine(id)?' chip--mine':''}${isFlex(fam(id))?' chip--flex':''}">${girlName(id)}</span>`).join('') || `<span class="muted">${t('deviation.geen_passagiers')}</span>`}</div>`;
  } else {
    // One-off pickup/drop-off place (US-15): a place from Beheer, or free input (an address or a point of interest).
    // Empty = the standard place of this shift. Free input lives on this ride only and is never stored as a place.
    const free = freeText(c);
    const showFree = !!free || !!S.devFree[key];
    const chosen = !free && locCfg.places.some(p=>p.id===c.locationId)? c.locationId : '';
    const stdName = locCfg.places.find(p=>p.id===carStdId(c, locCfg, day, direction)).name;
    const locationOptions = `<option value="" ${chosen===''&&!showFree?'selected':''}>${esc(t('loc.useDefault',{name:stdName}))}</option>` +
      locCfg.places.map(p=>`<option value="${p.id}" ${p.id===chosen?'selected':''}>${esc(p.name)}</option>`).join('') +
      `<option value="__free" ${showFree?'selected':''}>${esc(t('loc.freeOption'))}</option>`;
    const driverOk = c.driverFamilyId? (isFlex(fam(c.driverFamilyId)) || isAvailable(fam(c.driverFamilyId),day,direction)) : true;
    const driverOptions = `<option value="" ${!c.driverFamilyId?'selected':''}>${t('deviation.geen_chauffeur')}</option>` +
      allFamilies.map(([id,f])=>`<option value="${id}" ${id===c.driverFamilyId?'selected':''}>${esc(f.parentName)}${isFlex(f)? ' ('+t('flex.speelsterChauffeur')+')' : (isAvailable(f,day,direction)?'':t('deviation.geen_beschikbaarheid'))}</option>`).join('');
    const otherIdxs = cars.map((_,i)=>i).filter(i=>i!==idx);
    const destBtn = (k,name,city)=>`<button type="button" class="devDest${dest.key===k?' on':''}" data-devdest="${k}" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" aria-pressed="${dest.key===k}"><span class="devDestName">${esc(name)}</span><span class="devDestCity">${esc(city)}</span></button>`;
    const kidRows = girls.map(id=>{
      const active = S.devKid===`${key}|${id}`;
      const ctl = `data-day="${day}" data-direction="${direction}" data-caridx="${idx}" data-girl="${id}"`;
      return `<div class="devKidRow">
        <div class="devKidLine">
          <span class="devKidName${mine(id)?' mine':''}">${girlName(id)}</span>
          <button type="button" class="devKidMore${active?' on':''}" data-devkid="${key}|${id}" aria-expanded="${active}" aria-label="${esc(t('deviation.opties'))}">···</button>
        </div>
        ${active? `<div class="devKidActions">
          ${otherIdxs.map(i=>`<button type="button" class="devKidBtn" data-devmove="${i}" ${ctl}>${esc(t('deviation.naar_auto',{name: fam(cars[i].driverFamilyId).parentName||'?'}))}</button>`).join('')}
          <button type="button" class="devKidBtn danger devRemoveBtn" data-devremove="1" ${ctl} title="${t('deviation.verwijder_uit_auto')}" aria-label="${esc(t('deviation.verwijder_uit_auto'))}: ${girlName(id)}">${phIcon('trash')}</button>
        </div>` : ''}
      </div>`;
    }).join('') || `<p class="muted" style="margin:0">${t('deviation.geen_passagiers')}</p>`;
    body = `<div class="devForm">
      <div class="devFormTop">
        <label class="devField"><span>${t('deviation.vertrek')}</span><input type="time" class="devDeptimeInp devInput timeBig" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" value="${c.departureTime||''}" aria-label="${t('deviation.vertrektijd')}"></label>
        <label class="devField"><span>${t('deviation.chauffeur')}</span><select class="devDriverSel devInput" data-day="${day}" data-direction="${direction}" data-caridx="${idx}">${driverOptions}</select></label>
      </div>
      ${!driverOk? `<p class="fitbad" style="font-size:12px;margin:0">${phIcon('warning')} ${t('deviation.deze_ouder_heeft_voor_dit')}</p>` : ''}
      <label class="devField"><span>${t('deviation.ophalen')}</span><select class="devLocSel devInput" id="devLoc_${day}_${direction}_${idx}" data-day="${day}" data-direction="${direction}" data-caridx="${idx}">${locationOptions}</select></label>
      ${showFree? `<input type="text" class="devLocText devInput" id="devLocText_${day}_${direction}_${idx}" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" maxlength="${FREE_TEXT_MAX}" value="${esc(free)}" placeholder="${esc(t('loc.freePlaceholder'))}" aria-label="${esc(t('loc.freeLabel'))}">` : ''}
      <div class="devField"><span>${t('deviation.aankomst')}</span>
        <div class="devDestRow">${destBtn('AFC', locCfg.destination.name, CITY_AFC)}${destBtn('ATC', ATC_NAME, CITY_ATC)}</div>
      </div>
      <div class="devField"><span>${t('deviation.kinderen')}</span><div class="devKidList">${kidRows}</div></div>
    </div>`;
  }
  const toast = undo? `<div class="devToast" role="status"><span>${esc(undo.text)}</span><button type="button" class="devToastUndo" data-devundo="1">${t('deviation.ongedaan')}</button></div>` : '';
  return `<div class="devRide carCard devCard${open?' open':''}" data-devcar="${key}">${head}${body}${toast}</div>`;
}

export function renderDevDirection(day,direction){
  const cars = effectiveCars(day,direction);
  const dev = activeDeviation(day,direction);
  const allFamilies = Object.entries(S.families);
  const assignedIds = new Set(cars.flatMap(c=>c.girlIds));
  const unassigned = sortFamEntriesByGirl(allFamilies.filter(([id])=>!assignedIds.has(id)));

  const ctx = { allFamilies, myIdDev: myFamilyId(), locCfg: locationsCfg() };
  const cardsHtml = cars.map((c,idx)=>devRideHtml(day,direction,idx,cars,ctx)).join('') || `<p class="muted">${t('deviation.geen_ritten_gepland_in_het')}</p>`;

  const addOptions = cars.length? `<option value="">${t('deviation.voeg_toe_aan_auto')}</option>` + cars.map((c,i)=>`<option value="${i}">${t('deviation.auto')} ${esc(fam(c.driverFamilyId).parentName||'?')}</option>`).join('') : '';
  const unassignedHtml = unassigned.length? foldHtml(`others|${day}|${direction}`, t('deviation.andere_meiden'), `<p class="muted" style="margin-top:0">${t('deviation.ook_meiden_die_niet_standaard')}</p>
      ${unassigned.map(([id,f])=>`
        <div class="rowflex" style="padding:4px 0;border-bottom:1px solid var(--line)">
          <span style="flex:1">${esc(f.girlName||f.parentName||id)}</span>
          ${cars.length? `<select class="devAddSel" data-day="${day}" data-direction="${direction}" data-girl="${id}" style="width:auto;font-size:12px">${addOptions}</select>` : t('deviation.span_class_muted_nog_geen')}
        </div>`).join('')}`, 'group') : '';

  const focus = !!(S.deviationIntent && S.deviationIntent.some(c=>c.day===day && c.direction===direction));
  return `<div class="devDir${focus?' devFocus':''}">
    ${devDirHeader(direction,cars)}
    ${cardsHtml}
    ${backupHtml(day,direction,cars)}
    ${flexSignupHtml(day,direction,cars)}
    ${unassignedHtml}
    ${dev? `<button type="button" class="linkbtn" data-devreset="${day}|${direction}">${t('deviation.terug_naar_standaard_rooster')}</button>` : ''}
  </div>`;
}

export function attachDeviationHandlers(){
 try{
  document.querySelectorAll('.devDriverSel').forEach(sel=>sel.onchange=async ()=>{
    const {day,direction,caridx}=sel.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    cars[idx]={...cars[idx], driverFamilyId: sel.value||null};
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devLocSel').forEach(sel=>sel.onchange=async ()=>{
    const {day,direction,caridx}=sel.dataset; const idx=+caridx; const key=`${day}|${direction}|${idx}`;
    // "Ander adres…" only opens the free input; nothing is saved until something is typed.
    if(sel.value==='__free'){ S.devFree[key]=true; renderDeviationTab(); return; }
    const cars=effectiveCars(day,direction);
    // A place (or "Standaard") replaces any free input. undefined = back to the standard; saveDeviationCars leaves it out.
    cars[idx]={...cars[idx], locationId: sel.value||undefined, locationText: undefined};
    S.devFree[key]=false;
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devLocText').forEach(inp=>inp.onchange=async ()=>{
    const {day,direction,caridx}=inp.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    const text=inp.value.trim().slice(0,FREE_TEXT_MAX);
    // Free input is stored on this ride only (the deviation expires with the week); it never becomes a place in Beheer.
    cars[idx]= text? {...cars[idx], locationText:text, locationId:undefined} : {...cars[idx], locationText:undefined};
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devDeptimeInp').forEach(inp=>inp.onchange=async ()=>{
    const {day,direction,caridx}=inp.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    cars[idx]={...cars[idx], departureTime: inp.value};
    await saveDeviationCars(day,direction,cars);
  });
  // Remove / move a child: the card shows what happened with "Ongedaan" (devUndo) instead of a toast at the bottom of the screen.
  const afterChange = (day,direction,idx,prev,text)=>{
    S.devUndo = { key:`${day}|${direction}|${idx}`, text, day, direction, cars:prev };
    S.devKid = null;
    renderDeviationTab();
  };
  const snapshot = (day,direction)=>effectiveCars(day,direction).map(c=>({...c, girlIds:[...(c.girlIds||[])]}));
  document.querySelectorAll('[data-devtoggle]').forEach(btn=>btn.onclick=()=>{
    const key=btn.dataset.devtoggle; S.devOpen[key]=!S.devOpen[key];
    if(!S.devOpen[key]) S.devKid=null;
    hapticTap(); renderDeviationTab();
  });
  document.querySelectorAll('[data-devkid]').forEach(btn=>btn.onclick=()=>{
    S.devKid = S.devKid===btn.dataset.devkid? null : btn.dataset.devkid;
    renderDeviationTab();
  });
  document.querySelectorAll('[data-devdest]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,caridx,devdest}=btn.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    // Only a choice that differs from the car's own standard arrival is stored as a one-off change.
    cars[idx]={...cars[idx], destination: devdest===(cars[idx].stdDestination==='ATC'? 'ATC' : 'AFC')? undefined : devdest};
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devRemoveBtn').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,caridx,girl}=btn.dataset; const idx=+caridx;
    const prev=snapshot(day,direction);
    const cars=effectiveCars(day,direction);
    const newGirlIds=cars[idx].girlIds.filter(id=>id!==girl);
    cars[idx]={...cars[idx], girlIds:newGirlIds, departureTime: computeRideDeparture(day,direction,newGirlIds)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok) afterChange(day,direction,idx,prev,girlName(girl)+t('deviation.verwijderd_uit_deze_auto'));
  });
  document.querySelectorAll('[data-devmove]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,caridx,girl,devmove}=btn.dataset; const fromIdx=+caridx; const toIdx=+devmove;
    const prev=snapshot(day,direction);
    const cars=effectiveCars(day,direction);
    const newFrom=cars[fromIdx].girlIds.filter(id=>id!==girl);
    const newTo=[...cars[toIdx].girlIds, girl];
    const toSeatsAvail = cars[toIdx].driverFamilyId? seats(fam(cars[toIdx].driverFamilyId)) : null;
    const overfull = toSeatsAvail!=null && newTo.length>toSeatsAvail;
    cars[fromIdx]={...cars[fromIdx], girlIds:newFrom, departureTime: computeRideDeparture(day,direction,newFrom)};
    cars[toIdx]={...cars[toIdx], girlIds:newTo, departureTime: computeRideDeparture(day,direction,newTo)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok){
      afterChange(day,direction,fromIdx,prev, girlName(girl)+t('deviation.verplaatst'));
      if(overfull) showToast(t('deviation.deze_auto_zit_nu_vol', { p1: newTo.length, p2: toSeatsAvail }), {icon:'warning'});
    }
  });
  document.querySelectorAll('[data-devundo]').forEach(btn=>btn.onclick=async ()=>{
    const u=S.devUndo; if(!u) return;
    const ok = await saveDeviationCars(u.day,u.direction,u.cars);
    if(ok){ S.devUndo=null; renderDeviationTab(); }
  });
  document.querySelectorAll('.devAddSel').forEach(sel=>sel.onchange=async ()=>{
    if(!sel.value) return;
    const {day,direction,girl}=sel.dataset; const toIdx=+sel.value;
    const cars=effectiveCars(day,direction);
    const newTo=[...cars[toIdx].girlIds, girl];
    const toSeatsAvail = cars[toIdx].driverFamilyId? seats(fam(cars[toIdx].driverFamilyId)) : null;
    const overfull = toSeatsAvail!=null && newTo.length>toSeatsAvail;
    cars[toIdx]={...cars[toIdx], girlIds:newTo, departureTime: computeRideDeparture(day,direction,newTo)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok){
      if(overfull) showToast(t('deviation.deze_auto_zit_nu_vol_2', { p1: newTo.length, p2: toSeatsAvail }), {icon:'warning'});
      else showToast(girlName(girl)+t('deviation.toegevoegd'));
    }
  });
  function flexCtx(btn, attr){
    const [day,direction,id]=btn.dataset[attr].split('|');
    const timeEl=document.getElementById(`flexTime_${day}|${direction}|${id}`);
    const carEl=document.getElementById(`flexCar_${day}|${direction}|${id}`);
    return {day,direction,id,time:timeEl&&timeEl.value, carIdx:carEl&&carEl.value};
  }
  const lead = ()=> (S.settings&&S.settings.travelLeadMinutes)||60;
  document.querySelectorAll('[data-flexpass]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,id,time,carIdx}=flexCtx(btn,'flexpass');
    if(!time){ showToast(t('flex.chooseTime')); return; }
    if(carIdx===''||carIdx==null){ showToast(t('flex.chooseCarToast')); return; }
    const cars=flexJoinCar(effectiveCars(day,direction), +carIdx, id, time, direction, lead());
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.joined', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-flexdrive]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,id,time}=flexCtx(btn,'flexdrive');
    if(!time){ showToast(t('flex.chooseTime')); return; }
    const cars=flexDriveOwn(effectiveCars(day,direction), id, time, direction, lead());
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.driving', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-flexoff]').forEach(btn=>btn.onclick=async ()=>{
    const [day,direction,id]=btn.dataset.flexoff.split('|');
    const cars=flexSignOff(effectiveCars(day,direction), id);
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.removed', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-devreset]').forEach(btn=>btn.onclick=()=>twoStepConfirm(btn,t('deviation.zeker_terug_naar_standaard_rooster'),async ()=>{
    const [day,direction]=btn.dataset.devreset.split('|');
    // Written as an empty deviation instead of a delete: activeDeviation() ignores empty `cars`,
    // and deletes of a current-week deviation are refused by firestore.rules until it expires.
    try{ refreshWeekKey(); await db.doc("deviations/"+deviationKey(day,direction)).set({day,direction,weekKey:S.currentWeekKey,expiresAt:deviationExpiryMs(),cars:[]}); S.lastDeviationEditDay = day; recordLastUpdate('Deviation'); showToast(t('deviation.teruggezet_naar_standaard')); }
    catch(e){ showToast(t('data.mislukt')+(e&&e.message||e)); }
  }));
 }catch(e){ showToast(t('beheer.fout_bij_koppelen_knoppen')+(e&&e.message||e)); }
}
